function toTitleCase(str) {
  return str
    .trim()
    .toLowerCase()
    .split(' ')
    .filter(word => word.length > 0)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

function getGrade(score) {
  if (score >= 90) return 'A';
  if (score >= 80) return 'B';
  if (score >= 70) return 'C';
  if (score >= 60) return 'D';
  return 'F';
}

const gradeRank = { A: 4, B: 3, C: 2, D: 1, F: 0 };

const items = $input.all();

const transformed = items.map(item => {
  const data = item.json;
  const name = toTitleCase(data.name ?? '');
  const email = (data.email ?? '').trim().toLowerCase();
  const score = data.score ?? 0;
  const grade = getGrade(score);
  const summary = `${name} scored ${score} points (Grade ${grade})`;

  return {
    json: { name, email, score, grade, summary }
  };
});

const topPerformers = transformed.filter(item => gradeRank[item.json.grade] >= gradeRank['B']);

return topPerformers;
